/**
 * Canonical JSON and base64url.
 *
 * These two modules decide the exact bytes a signature covers, so a bug here is
 * not a formatting nit — it is either a signature that fails on genuine medicine
 * or a payload that can be mutated while its signature stays valid.
 *
 * The canonical-JSON cases are generated by Python and asserted byte for byte.
 * Regenerate with:
 *   python3 tests/fixtures/canonical-cases.py > tests/fixtures/canonical-cases.json
 */

import { test, describe } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';

import { CODES } from '../../src/core/errors.js';
import { canonicalJSONBytes, canonicalJSONString } from '../../src/core/canonical.js';
import { encodeB64u, decodeB64u, isB64u } from '../../src/core/base64url.js';

const ground = JSON.parse(
  readFileSync(new URL('../fixtures/canonical-cases.json', import.meta.url), 'utf8'),
);

const malformed = (err) => err.code === CODES.QR_MALFORMED;
const invalidPayload = (err) => err.code === CODES.PAYLOAD_INVALID;

describe('canonical JSON agrees with Python byte for byte', () => {
  for (const testCase of ground.cases) {
    test(testCase.name, () => {
      const bytes = canonicalJSONBytes(testCase.value);
      assert.equal(bytes.toString('hex'), testCase.canonical_hex);
      assert.equal(bytes.length, testCase.byte_length);
    });
  }

  test('all generated cases ran', () => {
    assert.ok(ground.cases.length >= 14, 'fixture looks truncated');
  });
});

describe('canonical JSON rules', () => {
  test('keys are sorted recursively, not just at the top level', () => {
    assert.equal(
      canonicalJSONString({ b: { d: 1, c: 2 }, a: 3 }),
      '{"a":3,"b":{"c":2,"d":1}}',
    );
  });

  test('keys above the BMP sort by code point, not by UTF-16 unit', () => {
    // The bug this guards against: [...].sort() would put the emoji first
    // because its leading surrogate (0xD83D) is below U+FF21.
    const text = canonicalJSONString({ '\u{1F600}': 1, 'Ａ': 2 });
    assert.equal(text.indexOf('Ａ') < text.indexOf('\u{1F600}'), true);
  });

  test('no whitespace is emitted', () => {
    const text = canonicalJSONString({ a: 1, b: [1, 2], c: { d: 3 } });
    assert.equal(/\s/.test(text), false);
  });

  test('array order is preserved — excipient order is signed data', () => {
    assert.equal(
      canonicalJSONString({ ex: ['starch', 'lactose', 'aspartame'] }),
      '{"ex":["starch","lactose","aspartame"]}',
    );
  });

  test('non-ASCII is emitted raw, never \\u-escaped', () => {
    const text = canonicalJSONString({ k: 'पैरासिटामोल' });
    assert.equal(text.includes('पैरासिटामोल'), true);
    assert.equal(text.includes('\\u'), false);
  });

  test('undefined properties are dropped, matching JSON.stringify', () => {
    assert.equal(canonicalJSONString({ a: 1, b: undefined }), '{"a":1}');
  });

  test('rejects non-integer numbers rather than guessing a representation', () => {
    // Python and JavaScript disagree on the shortest form of some floats, and a
    // signature covers bytes. Nothing signed in TrueMed contains a float, so
    // this fails loudly instead of silently diverging.
    assert.throws(() => canonicalJSONString({ t: 4.5 }), invalidPayload);
    assert.throws(() => canonicalJSONString({ t: 0.1 }), invalidPayload);
    assert.throws(() => canonicalJSONString({ t: -2.75 }), invalidPayload);
  });

  test('rejects integers past 2^53, where the two languages format differently', () => {
    // Number.isInteger(1e30) is true, so an integer check alone lets these
    // through. JavaScript writes 1e21 and above in exponential notation
    // ("1e+21"); Python's arbitrary-precision ints never do
    // ("1000000000000000000000"). Above 2^53 a JavaScript number cannot
    // round-trip at all.
    for (const big of [1e21, 1e30, 2 ** 53, Number.MAX_SAFE_INTEGER + 2, -(2 ** 53)]) {
      assert.throws(() => canonicalJSONString({ t: big }), invalidPayload, String(big));
    }
  });

  test('rejects NaN and Infinity, which JSON cannot represent', () => {
    assert.throws(() => canonicalJSONString({ t: NaN }), invalidPayload);
    assert.throws(() => canonicalJSONString({ t: Infinity }), invalidPayload);
    assert.throws(() => canonicalJSONString({ t: -Infinity }), invalidPayload);
  });

  test('rejects values JSON has no representation for', () => {
    assert.throws(() => canonicalJSONString({ f: () => 1 }), invalidPayload);
    assert.throws(() => canonicalJSONString({ s: Symbol('x') }), invalidPayload);
    assert.throws(() => canonicalJSONString({ b: 1n }), invalidPayload);
  });

  test('names the offending path so a failure is diagnosable', () => {
    assert.throws(
      () => canonicalJSONString({ outer: { inner: [1, 2.5] } }),
      (err) => /outer\.inner\[1\]/.test(err.message),
    );
  });

  test('accepts integers at the safe-integer boundary', () => {
    assert.equal(
      canonicalJSONString({ n: Number.MAX_SAFE_INTEGER }),
      '{"n":9007199254740991}',
    );
    assert.equal(canonicalJSONString({ n: -0 }), '{"n":0}');
  });

  test('canonicalJSONBytes is the UTF-8 encoding of canonicalJSONString', () => {
    const value = { k: 'पैरासिटामोल ५००', n: 1 };
    assert.equal(
      canonicalJSONBytes(value).toString('hex'),
      Buffer.from(canonicalJSONString(value), 'utf8').toString('hex'),
    );
  });

  test('a Devanagari field costs three bytes per character, not one', () => {
    // The reason MAX_PAYLOAD_BYTES is a byte budget rather than a character one.
    const bytes = canonicalJSONBytes({ k: 'पैरासिटामोल' });
    assert.ok(bytes.length > JSON.stringify({ k: 'पैरासिटामोल' }).length);
  });
});

describe('base64url encoding', () => {
  test('round-trips arbitrary bytes', () => {
    for (let len = 0; len <= 64; len += 1) {
      const raw = Buffer.alloc(len, 0xab);
      assert.equal(decodeB64u(encodeB64u(raw)).toString('hex'), raw.toString('hex'), `len ${len}`);
    }
  });

  test('emits no padding', () => {
    for (const len of [1, 2, 3, 4, 5]) {
      assert.equal(encodeB64u(Buffer.alloc(len)).includes('='), false, `len ${len}`);
    }
  });

  test('uses the URL-safe alphabet, never + or /', () => {
    // 0xFB 0xFF 0xBF encodes to characters that differ between the two alphabets.
    const text = encodeB64u(Buffer.from([0xfb, 0xff, 0xbf]));
    assert.equal(/[+/]/.test(text), false);
    assert.equal(isB64u(text), true);
  });

  test('a 64-byte signature is 86 characters, as the wire overhead assumes', () => {
    assert.equal(encodeB64u(Buffer.alloc(64)).length, 86);
  });
});

describe('base64url decoding is strict', () => {
  test('rejects the standard-alphabet characters + and /', () => {
    // Buffer.from treats -/+ and _// as interchangeable, so "A-AA" and "A+AA"
    // decode identically. That gives one payload many wire spellings, and the
    // clone defence counts scans per distinct code — so an attacker could mint
    // unlimited variants of one genuine QR and never trip the counter.
    assert.throws(() => decodeB64u('A+AA', 'payload'), malformed);
    assert.throws(() => decodeB64u('A/AA', 'payload'), malformed);
  });

  test('rejects padding', () => {
    assert.throws(() => decodeB64u('QQ==', 'payload'), malformed);
    assert.throws(() => decodeB64u('QUJD=', 'payload'), malformed);
  });

  test('rejects whitespace, which Buffer.from would silently skip', () => {
    assert.throws(() => decodeB64u('A A A', 'payload'), malformed);
    assert.throws(() => decodeB64u('QUJD ', 'payload'), malformed);
    assert.throws(() => decodeB64u(`QU${String.fromCharCode(10)}JD`, 'payload'), malformed);
  });

  test('rejects a length that cannot be a base64 group', () => {
    // One leftover character carries 6 bits; no byte boundary falls there.
    assert.throws(() => decodeB64u('A', 'payload'), malformed);
    assert.throws(() => decodeB64u('QUJDQ', 'payload'), malformed);
  });

  test('rejects non-canonical trailing bits', () => {
    // "QQE" and "QQF" both decode to the same two bytes, because the final
    // character's low bits are ignored. Same malleability problem as the
    // alphabet: two spellings, one payload, clone counting defeated.
    assert.equal(decodeB64u('QQE', 'payload').toString('hex'), '4101');
    assert.throws(() => decodeB64u('QQF', 'payload'), malformed);
  });

  test('rejects non-strings', () => {
    for (const bad of [null, undefined, 42, Buffer.from('QQ'), {}]) {
      assert.throws(() => decodeB64u(bad, 'payload'), malformed);
    }
  });

  test('accepts the empty string, which is zero bytes', () => {
    // codec.js rejects an empty payload part separately, with a clearer message.
    assert.equal(decodeB64u('', 'payload').length, 0);
  });

  test('the error message names the field and the offending position', () => {
    assert.throws(
      () => decodeB64u('AB+D', 'signature'),
      (err) => /signature/.test(err.message) && /position 2/.test(err.message),
    );
  });

  test('isB64u is a predicate, not a validator', () => {
    // It checks the alphabet only; length and canonicity are decodeB64u's job.
    assert.equal(isB64u('QUJD'), true);
    assert.equal(isB64u('A'), true);
    assert.equal(isB64u('A+A'), false);
    assert.equal(isB64u('QQ=='), false);
    assert.equal(isB64u(null), false);
  });
});
